-- ============================================================================
-- V007: Requirement sourcing — links HPA inspection requirement codes (tuso
--       manual-derived content, HPA-2017-V1) to marketplace sourcing
--       CATEGORIES. Regulator-neutral by construction: requirements map to
--       categories, never to suppliers or SKUs; the regulator's checklist
--       content is never touched. The mapping is curated, versioned,
--       human-approved content and explicitly partial — staffing, room
--       dimensions and process requirements are not mappable.
-- ============================================================================

CREATE TABLE IF NOT EXISTS msika_sourcing_categories (
    code                VARCHAR(64) PRIMARY KEY,
    label               VARCHAR(200) NOT NULL,
    description         TEXT,
    restricted          BOOLEAN NOT NULL DEFAULT FALSE,
    required_credential VARCHAR(64),           -- e.g. PHARMACEUTICAL_WHOLESALER_CERTIFICATE
    search_terms        TEXT[],
    status              VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',   -- ACTIVE | RETIRED
    version             INTEGER NOT NULL DEFAULT 1,
    provenance          TEXT
);

CREATE TABLE IF NOT EXISTS msika_requirement_sourcing_map (
    map_id                 VARCHAR(26) PRIMARY KEY,
    requirement_code       VARCHAR(64) NOT NULL,
    sourcing_category_code VARCHAR(64) NOT NULL REFERENCES msika_sourcing_categories(code),
    status                 VARCHAR(16) NOT NULL DEFAULT 'APPROVED',  -- DRAFT | APPROVED | RETIRED
    provenance             TEXT,
    approved_by            VARCHAR(128),
    version                INTEGER NOT NULL DEFAULT 1,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (requirement_code, sourcing_category_code, version)
);
CREATE INDEX IF NOT EXISTS idx_msika_req_map_code
    ON msika_requirement_sourcing_map(requirement_code) WHERE status = 'APPROVED';

-- Listings join to sourcing categories via their catalog item.
ALTER TABLE msika_catalog_items ADD COLUMN IF NOT EXISTS sourcing_category_code VARCHAR(64);
CREATE INDEX IF NOT EXISTS idx_msika_catalog_items_sourcing_cat
    ON msika_catalog_items(sourcing_category_code);

-- ----------------------------------------------------------------------------
-- Curated seeds (authored via scripts/data/generate-sourcing-map-draft.mjs,
-- human-curated; provenance HPA-2017-V1 per row).
-- ----------------------------------------------------------------------------
ON CONFLICT (code) DO NOTHING;
ON CONFLICT (requirement_code, sourcing_category_code, version) DO NOTHING;
